def parse_range(header, size):
    """
    Parse an RFC 7233 Range header for bytes.

    Args:
        header (str): The value of the Range header (e.g., "bytes=0-499").
        size (int): The total size of the resource in bytes.

    Returns:
        list: A list of (start, end) tuples representing inclusive byte offsets,
              or None if the header is unsatisfiable (all ranges are invalid).
    """
    if not header.startswith("bytes="):
        return None

    ranges_str = header[6:]  # Remove "bytes=" prefix
    if not ranges_str:
        return None

    ranges = []
    parts = ranges_str.split(",")

    for part in parts:
        part = part.strip()
        if not part:
            continue

        if "-" not in part:
            continue

        left, right = part.split("-", 1)
        left = left.strip()
        right = right.strip()

        start = None
        end = None

        # Handle suffix range: "-500"
        if not left:
            if not right:
                continue  # Invalid: just "-"
            try:
                suffix_length = int(right)
            except ValueError:
                continue
            if suffix_length <= 0:
                continue
            start = size - suffix_length
            if start < 0:
                start = 0
            end = size - 1
        # Handle normal range: "0-499" or "500-"
        elif not right:
            try:
                start = int(left)
            except ValueError:
                continue
            if start < 0:
                continue
            end = size - 1
        else:
            try:
                start = int(left)
            except ValueError:
                continue
            if start < 0:
                continue
            try:
                end = int(right)
            except ValueError:
                continue
            if end < start:
                continue

        # Validate and clamp range
        if start is not None and start >= size:
            continue  # Unsatisfiable

        if end is not None and end >= size:
            end = size - 1

        if start is not None and end is not None:
            if start > end:
                continue  # Invalid range
            ranges.append((start, end))
        elif start is not None and end is None:
            # Suffix range already handled above, but if we got here with start only
            # it means right was empty, so end is size-1
            if start >= size:
                continue
            ranges.append((start, size - 1))
        elif start is None and end is not None:
            # This case shouldn't happen with the logic above unless right was present but left empty
            # which is handled in the suffix block. If we are here, it's an error or skip.
            continue

    if not ranges:
        return None

    return ranges
