        prev_node = node.prev
        next_node = node.next
        if prev_node:
            prev_node.next = next_node
        if next_node:
            next_node.prev = prev_node
        if node == self.key_to_node.get(node.key).next:
            self.key_to_node[node.key] = None

    def _add_to_head(self, node):
        head = self.key_to_node.get(node.key).next
        node.next = head
        node.prev = head.prev
        if head.prev:
            head.prev.next = node
        head.prev = node

    def _remove_from_head(self):
        head = self.key_to_node.get(None).next
        self._remove_node(head)
