import re
from datetime import datetime, timedelta
from typing import List, Tuple, Optional, Union

def parse_field(field: str, min_val: int, max_val: int) -> List[int]:
    """Parse a single cron field into a sorted list of integers."""
    if not field:
        raise ValueError("Empty field")

    parts = field.split(',')
    result = set()

    for part in parts:
        part = part.strip()
        if not part:
            raise ValueError("Empty part in field")

        if part == '*':
            result.update(range(min_val, max_val + 1))
        elif '/' in part:
            base, step = part.split('/')
            step = int(step)
            if step <= 0:
                raise ValueError(f"Invalid step: {step}")
            if base == '*':
                start = min_val
                end = max_val
            elif '-' in base:
                start, end = map(int, base.split('-'))
                if start < min_val or end > max_val or start > end:
                    raise ValueError(f"Invalid range in step expression: {base}")
            else:
                start = int(base)
                end = max_val

            for i in range(start, end + 1, step):
                if min_val <= i <= max_val:
                    result.add(i)
        elif '-' in part:
            start, end = map(int, part.split('-'))
            if start < min_val or end > max_val or start > end:
                raise ValueError(f"Invalid range: {part}")
            result.update(range(start, end + 1))
        else:
            val = int(part)
            if val < min_val or val > max_val:
                raise ValueError(f"Value out of range: {val}")
            result.add(val)

    return sorted(result)

def parse_cron(expr: str) -> Tuple[List[int], List[int], List[int], List[int], List[int]]:
    """Parse a 5-field cron expression."""
    fields = expr.strip().split()
    if len(fields) != 5:
        raise ValueError(f"Expected 5 fields, got {len(fields)}")

    minute = parse_field(fields[0], 0, 59)
    hour = parse_field(fields[1], 0, 23)
    day_of_month = parse_field(fields[2], 1, 31)
    month = parse_field(fields[3], 1, 12)
    day_of_week = parse_field(fields[4], 0, 6)

    return minute, hour, day_of_month, month, day_of_week

def is_valid_date(year: int, month: int, day: int) -> bool:
    """Check if a date is valid."""
    try:
        datetime(year, month, day)
        return True
    except ValueError:
        return False

def next_fire(expr: str, after: datetime) -> datetime:
    """
    Return the next datetime strictly after `after` at which the cron expression fires.
    """
    minute, hour, day_of_month, month, day_of_week = parse_cron(expr)

    # Determine if day-of-month and day-of-week are both restricted
    dom_restricted = day_of_month != list(range(1, 32))
    dow_restricted = day_of_week != list(range(0, 7))

    current = after.replace(second=0, microsecond=0)
    current = current + timedelta(days=1)  # Start searching from the next day

    # Search for up to 400 years to cover the full Gregorian cycle
    max_iterations = 400 * 366
    for _ in range(max_iterations):
        year = current.year
        month = current.month
        day = current.day
        hour = current.hour
        minute = current.minute

        # Check month
        if month not in month:
            # Move to next month
            if month == 12:
                current = current.replace(year=year + 1, month=1, day=1, hour=0, minute=0)
            else:
                current = current.replace(month=month + 1, day=1, hour=0, minute=0)
            continue

        # Check day rules
        if dom_restricted and dow_restricted:
            # Fires if day matches EITHER field
            if day not in day_of_month and day not in day_of_week:
                # Move to next day
                if day == 31:
                    current = current.replace(day=1, hour=0, minute=0)
                    if current.month == 12:
                        current = current.replace(year=current.year + 1, month=1, day=1, hour=0, minute=0)
                    else:
                        current = current.replace(month=current.month + 1, day=1, hour=0, minute=0)
                else:
                    current = current.replace(day=day + 1, hour=0, minute=0)
                continue
        elif dom_restricted:
            if day not in day_of_month:
                if day == 31:
                    current = current.replace(day=1, hour=0, minute=0)
                    if current.month == 12:
                        current = current.replace(year=current.year + 1, month=1, day=1, hour=0, minute=0)
                    else:
                        current = current.replace(month=current.month + 1, day=1, hour=0, minute=0)
                else:
                    current = current.replace(day=day + 1, hour=0, minute=0)
                continue
        elif dow_restricted:
            if day not in day_of_week:
                if day == 31:
                    current = current.replace(day=1, hour=0, minute=0)
                    if current.month == 12:
                        current = current.replace(year=current.year + 1, month=1, day=1, hour=0, minute=0)
                    else:
                        current = current.replace(month=current.month + 1, day=1, hour=0, minute=0)
                else:
                    current = current.replace(day=day + 1, hour=0, minute=0)
                continue

        # Check hour
        if hour not in hour:
            if hour == 23:
                current = current.replace(hour=0, minute=0)
                if current.month == 12:
                    current = current.replace(year=current.year + 1, month=1, day=1, hour=0, minute=0)
                else:
                    current = current.replace(month=current.month + 1, day=1, hour=0, minute=0)
            else:
                current = current.replace(hour=hour + 1, minute=0)
            continue

        # Check minute
        if minute not in minute:
            if minute == 59:
                current = current.replace(minute=0)
                if current.hour == 23:
                    current = current.replace(hour=0)
                    if current.month == 12:
                        current = current.replace(year=current.year + 1, month=1, day=1, hour=0, minute=0)
                    else:
                        current = current.replace(month=current.month + 1, day=1, hour=0, minute=0)
                else:
                    current = current.replace(hour=current.hour + 1, minute=0)
            else:
                current = current.replace(minute=minute + 1)
            continue

        # All fields match
        return current

    raise RuntimeError("Failed to find next fire time within expected bounds")
