import heapq

def topo_lex(graph):
    # Collect all nodes
    all_nodes = set(graph.keys())
    for successors in graph.values():
        all_nodes.update(successors)

    # Build in-degree map
    in_degree = {node: 0 for node in all_nodes}

    for node in graph:
        for successor in graph[node]:
            in_degree[successor] += 1

    # Min-heap to store nodes with in-degree 0, ordered lexicographically
    heap = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []

    while heap:
        node = heapq.heappop(heap)
        result.append(node)

        # If this node has successors, decrement their in-degrees
        if node in graph:
            for successor in graph[node]:
                in_degree[successor] -= 1
                if in_degree[successor] == 0:
                    heapq.heappush(heap, successor)

    # Check for cycle
    if len(result) != len(all_nodes):
        return None

    return result

