const { URLSearchParams } = require('url');

function decode(str) {
  if (typeof str !== 'string') return str;
  return decodeURIComponent(str.replace(/\+/g, ' '));
}

function parseQuery(qs) {
  if (typeof qs !== 'string') return qs;
  qs = qs.replace(/^\?/, '');
  if (!qs) return {};

  const result = {};
  const pairs = qs.split('&');

  for (const pair of pairs) {
    if (!pair) continue;
    const eqIndex = pair.indexOf('=');
    let key, value;

    if (eqIndex === -1) {
      key = decode(pair);
      value = '';
    } else {
      key = decode(pair.slice(0, eqIndex));
      value = decode(pair.slice(eqIndex + 1));
    }

    if (key === '') continue;

    if (result[key] === undefined) {
      result[key] = value;
    } else if (Array.isArray(result[key])) {
      result[key].push(value);
    } else {
      result[key] = [result[key], value];
    }
  }

  return convertToNested(result);
}

function convertToNested(obj) {
  const result = {};
  for (const key in obj) {
    if (!obj.hasOwnProperty(key)) continue;
    const val = obj[key];
    if (Array.isArray(val)) {
      if (val.length === 1) {
        result[key] = convertToNested({ [key[0]]: val[0] });
      } else {
        result[key] = val.map(v => convertToNested({ [key[0]]: v }));
      }
    } else {
      result[key] = convertToNested({ [key]: val });
    }
  }
  return result;
}

function buildQuery(obj) {
  if (obj === null || obj === undefined) return '';
  if (typeof obj !== 'object') return encodeURIComponent(String(obj));

  const parts = [];
  const keys = Object.keys(obj).sort();

  for (const key of keys) {
    const val = obj[key];
    if (val === null || val === undefined) continue;

    if (Array.isArray(val)) {
      for (let i = 0; i < val.length; i++) {
        parts.push(encodeKey(key, i) + '=' + encodeURIComponent(val[i]));
      }
    } else if (typeof val === 'object') {
      const nested = buildQuery(val);
      if (nested) {
        parts.push(encodeKey(key, '') + '=' + nested);
      }
    } else {
      parts.push(encodeKey(key, '') + '=' + encodeURIComponent(val));
    }
  }

  return parts.join('&');
}

function encodeKey(key, index) {
  if (index === undefined) {
    return key;
  }
  return key + '[]';
}

module.exports = { parseQuery, buildQuery };

