export type RouteParams<T extends Record<string, string>> = {
  [K in keyof T]: T[K] extends `:${infer Name}` ? Name : never;
}[keyof T];

export type RoutePath<T extends Record<string, string>> = {
  [K in keyof T]: T[K] extends `:${infer _}` ? string : never;
}[keyof T];

export type RouteHandler<T extends Record<string, string>> = T extends never
  ? () => string
  : <P extends RouteParams<T>>(params: P) => string;

export function defineRoutes<T extends Record<string, string>>(
  routes: T
): {
  [K in keyof T]: RouteHandler<T[K]>;
} {
  const handlers: any = {};

  for (const [name, path] of Object.entries(routes)) {
    const paramNames = path.match(/:(\w+)/g)?.map((m) => m.slice(1)) || [];
    const paramTypes: Record<string, string> = {};
    paramNames.forEach((p) => {
      paramTypes[p] = 'string';
    });

    const paramKeys = paramNames.length === 0 ? [] : paramNames;

    const handler: any = (params: Record<string, string>) => {
      if (paramKeys.length === 0) {
        return path;
      }
      if (Object.keys(params).length !== paramKeys.length) {
        throw new Error(`Route "${name}" expects exactly ${paramKeys.length} parameters, got ${Object.keys(params).length}`);
      }
      let result = path;
      for (const key of paramKeys) {
        result = result.replace(`:${key}`, params[key]);
      }
      return result;
    };

    handlers[name] = handler;
  }

  return handlers;
}

